<script setup lang="ts">
const niches = ref<any[]>([]); const angles = ref<any[]>([]); const copies = ref<any[]>([]); const metrics = ref<any>({ totals: {}, byAngle: [] })
async function load() { [niches.value, angles.value, copies.value, metrics.value] = await Promise.all([$fetch('/api/niches'), $fetch('/api/angles'), $fetch('/api/copies'), $fetch('/api/metrics')]) }; onMounted(load)
async function deleteEverything() { if (!confirm('Esta acción eliminará TODOS los nichos, ángulos y componentes. No se puede deshacer. ¿Continuar?')) return; if (prompt('Escribe ELIMINAR TODO para confirmar:') !== 'ELIMINAR TODO') return; await $fetch('/api/admin/reset', { method: 'POST', body: { confirmation: 'ELIMINAR TODO' } }); await load() }
</script>
<template><div class="mx-auto max-w-7xl px-5 py-10 lg:px-8"><div class="mb-10"><p class="eyebrow">Centro de control</p><h1 class="mt-3 text-4xl font-bold">Administración</h1><p class="mt-3 text-slate-500">Gestiona la arquitectura que alimenta el generador público.</p></div><div class="grid gap-4 sm:grid-cols-3"><StatCard label="Nichos" :value="niches.length" detail="Activos y archivados" /><StatCard label="Ángulos" :value="angles.length" detail="Todos los enfoques" tone="bg-mint/10 text-mint" /><StatCard label="Componentes" :value="copies.length" detail="Líneas de copy" tone="bg-amber-100 text-amber-700" /></div><div class="card mt-8 p-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="eyebrow">Métricas globales</p><h2 class="mt-1 text-xl font-bold">Uso por ángulo</h2></div><p class="text-sm text-slate-500">{{ metrics.totals.timesUsed || 0 }} usos acumulados · {{ metrics.totals.used || 0 }} líneas actualmente usadas</p></div><div class="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><div v-for="row in metrics.byAngle.slice(0, 9)" :key="row.angleId" class="rounded-xl bg-slate-50 p-3 text-sm dark:bg-slate-800"><p class="font-semibold">{{ row.name }}</p><p class="mt-1 text-xs text-slate-500">{{ row.timesUsed }} usos · {{ row.used }}/{{ row.components }} activas</p></div></div></div><div class="mt-8 grid gap-5 md:grid-cols-4"><NuxtLink to="/admin/angles" class="card p-6 transition hover:-translate-y-1"><p class="text-2xl">◒</p><h2 class="mt-5 text-xl font-bold">Nichos y ángulos</h2><p class="mt-2 text-sm text-slate-500">Crea estructuras, descripciones, riesgo y activa o desactiva ángulos.</p><span class="mt-6 block text-sm font-bold text-brand">Gestionar →</span></NuxtLink><NuxtLink to="/admin/copies" class="card p-6 transition hover:-translate-y-1"><p class="text-2xl">✦</p><h2 class="mt-5 text-xl font-bold">Banco de copy</h2><p class="mt-2 text-sm text-slate-500">Añade, edita, elimina o carga masivamente líneas por categoría.</p><span class="mt-6 block text-sm font-bold text-brand">Gestionar →</span></NuxtLink><NuxtLink to="/admin/import" class="card p-6 transition hover:-translate-y-1"><p class="text-2xl">⇧</p><h2 class="mt-5 text-xl font-bold">Importar archivo</h2><p class="mt-2 text-sm text-slate-500">Parsea HTML/TXT, revisa categorías y carga frases al banco.</p><span class="mt-6 block text-sm font-bold text-brand">Importar →</span></NuxtLink><NuxtLink to="/" class="card bg-ink p-6 text-white transition hover:-translate-y-1"><p class="text-2xl">↗</p><h2 class="mt-5 text-xl font-bold">Ver generador</h2><p class="mt-2 text-sm text-slate-300">Comprueba cómo verá el usuario el contenido publicado.</p><span class="mt-6 block text-sm font-bold text-indigo-300">Abrir →</span></NuxtLink></div><div class="mt-8 flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-red-200 bg-red-50 p-5"><div><p class="font-bold text-red-800">Zona peligrosa</p><p class="mt-1 text-sm text-red-700">Elimina todos los nichos, ángulos y componentes de la aplicación.</p></div><button class="btn !bg-red-600 !text-white hover:!bg-red-700" @click="deleteEverything">Eliminar toda la base de datos</button></div></div></template>
